//! Recognises messages generated by Uptime Kuma's Gotify sender:
//! `[<monitor>] [🔴 Down] <details>` and `[<monitor>] [✅ Up] <details>`.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum KumaStatus {
    Down,
    Up,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct KumaEvent {
    pub monitor: String,
    pub status: KumaStatus,
    pub details: String,
}

const DOWN: &str = "] [🔴 Down]";
const UP: &str = "] [✅ Up]";

pub fn parse_kuma(text: &str) -> Option<KumaEvent> {
    let rest = text.strip_prefix('[')?;
    // The first status marker ends the monitor name, so names may contain ']'.
    let found = [(DOWN, KumaStatus::Down), (UP, KumaStatus::Up)]
        .into_iter()
        .filter_map(|(marker, status)| rest.find(marker).map(|at| (at, marker, status)))
        .min_by_key(|(at, _, _)| *at)?;
    let (at, marker, status) = found;
    let monitor = &rest[..at];
    if monitor.is_empty() {
        return None;
    }
    let after = &rest[at + marker.len()..];
    let details = after.strip_prefix(' ').unwrap_or(after);
    Some(KumaEvent { monitor: monitor.to_string(), status, details: details.to_string() })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_down() {
        let e = parse_kuma("[web01] [🔴 Down] timeout of 48000ms exceeded").unwrap();
        assert_eq!(e.monitor, "web01");
        assert_eq!(e.status, KumaStatus::Down);
        assert_eq!(e.details, "timeout of 48000ms exceeded");
    }

    #[test]
    fn parse_up() {
        let e = parse_kuma("[web01] [✅ Up] 200 - OK").unwrap();
        assert_eq!(e.status, KumaStatus::Up);
        assert_eq!(e.details, "200 - OK");
    }

    #[test]
    fn parse_without_details() {
        let e = parse_kuma("[web01] [✅ Up]").unwrap();
        assert_eq!(e.details, "");
    }

    #[test]
    fn parse_name_with_bracket() {
        let e = parse_kuma("[api [eu]] [🔴 Down] x").unwrap();
        assert_eq!(e.monitor, "api [eu]");
    }

    #[test]
    fn parse_rejects_other() {
        assert_eq!(parse_kuma("hello"), None);
        assert_eq!(parse_kuma("[web01] [⚠ Pending] x"), None);
        assert_eq!(parse_kuma("web01 [🔴 Down] x"), None);
        assert_eq!(parse_kuma("[] [🔴 Down] x"), None);
    }
}
